const VERSION='exercise-v2.3.0';
const ASSETS=['./','./index.html','./styles.css','./app.js','./engine.js','./training.js','./guides.js','./offline.js','./llm-coach.js','./favicon.svg','./manifest.webmanifest','./vendor/vision_bundle.mjs','./vendor/pose_landmarker_lite.task','./vendor/wasm/vision_wasm_internal.js','./vendor/wasm/vision_wasm_internal.wasm','./vendor/wasm/vision_wasm_nosimd_internal.js','./vendor/wasm/vision_wasm_nosimd_internal.wasm',...['squat','curl','pushup','plank','press','pullup'].map(k=>'./guides/'+k+'.webm')];
async function report(done){for(const client of await self.clients.matchAll({type:'window',includeUncontrolled:true}))client.postMessage({type:'OFFLINE_PROGRESS',done,total:ASSETS.length});}
async function fill(cache,missingOnly=false){let done=0;for(const asset of ASSETS){if(!missingOnly||!await cache.match(asset))await cache.add(new Request(asset,{cache:'reload'}));await report(++done);}}
self.addEventListener('install',event=>event.waitUntil((async()=>{const cache=await caches.open(VERSION);await fill(cache);await self.skipWaiting();})()));
self.addEventListener('activate',event=>event.waitUntil((async()=>{for(const key of await caches.keys())if(key.startsWith('exercise-v')&&key!==VERSION)await caches.delete(key);await self.clients.claim();})()));
self.addEventListener('message',event=>{if(event.data==='REPAIR')event.waitUntil((async()=>{try{const cache=await caches.open(VERSION);await fill(cache,true);event.ports[0]?.postMessage({ready:true});}catch{event.ports[0]?.postMessage({ready:false});}})());if(event.data==='STATUS')event.waitUntil((async()=>{const cache=await caches.open(VERSION);const all=await Promise.all(ASSETS.map(p=>cache.match(p)));event.ports[0]?.postMessage({ready:all.every(Boolean)});})());});
self.addEventListener('fetch',event=>{
 if(event.request.method!=='GET'||new URL(event.request.url).origin!==self.location.origin)return;
 event.respondWith((async()=>{const cache=await caches.open(VERSION);const found=await cache.match(event.request,{ignoreSearch:true});if(found){const range=event.request.headers.get('range');if(range&&event.request.url.endsWith('.webm')){const bytes=await found.arrayBuffer();const match=/bytes=(\d+)-(\d*)/.exec(range);if(match){const start=Number(match[1]),end=Math.min(match[2]?Number(match[2]):bytes.byteLength-1,bytes.byteLength-1);if(start> end)return new Response(null,{status:416,headers:{'Content-Range':`bytes */${bytes.byteLength}`}});return new Response(bytes.slice(start,end+1),{status:206,headers:{'Content-Type':'video/webm','Content-Range':`bytes ${start}-${end}/${bytes.byteLength}`,'Content-Length':String(end-start+1),'Accept-Ranges':'bytes'}});}}return found;}return fetch(event.request);})());
});

